"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[5210],{38117:e=>{e.exports=JSON.parse('{"functions":[{"name":"chooseGameMap","desc":"Picks a random map for a game mode from its own `config.maps` list and returns\\nthe registered [Map] record.\\n\\nAsserts on a malformed mode. Returns `nil` if the drawn name is not in the\\nregistry \u2014 which happens when a mode lists a map that failed validation in\\n[MinigameData] \u2014 so callers must handle a nil result.","params":[{"name":"gameMode","desc":"","lua_type":"MinigameTypes.GameMode"}],"returns":[{"desc":"","lua_type":"MinigameTypes.Map?"}],"function_type":"static","source":{"line":70,"path":"src/Server/Features/Minigames/MinigameUtil.luau"}},{"name":"set","desc":"Writes a cross-system variable as an attribute on the shared `Variables`\\nConfiguration. Replicates to clients automatically and persists across rounds.","params":[{"name":"attribute","desc":"Variable name","lua_type":"string"},{"name":"value","desc":"Any attribute-compatible value","lua_type":"any"}],"returns":[],"function_type":"static","source":{"line":89,"path":"src/Server/Features/Minigames/MinigameUtil.luau"}},{"name":"get","desc":"Reads a cross-system variable. Returns `nil` for anything never set.","params":[{"name":"key","desc":"Variable name","lua_type":"string"}],"returns":[{"desc":"","lua_type":"any"}],"function_type":"static","source":{"line":102,"path":"src/Server/Features/Minigames/MinigameUtil.luau"}},{"name":"calculateMapLoadTime","desc":"Estimates how long clients need to stream a map in, so [GameService] can hold\\nthe round back until players can actually see it.\\n\\nThe estimate is one second per 896 parts, floored \u2014 a rough constant tuned\\nempirically rather than measured \u2014 and is never allowed below\\n`MinigameConfig.voteResultTime`, so the vote result stays on screen for its full\\nduration even for a trivially small map.","params":[{"name":"map","desc":"","lua_type":"Model"}],"returns":[{"desc":"Seconds to wait","lua_type":"number"}],"function_type":"static","source":{"line":122,"path":"src/Server/Features/Minigames/MinigameUtil.luau"}},{"name":"pushError","desc":"Reports a minigame error into the analytics pipeline, optionally attributed to\\nthe client that caused it.","params":[{"name":"err","desc":"Error description","lua_type":"string"},{"name":"userId","desc":"UserId of the client responsible, if any","lua_type":"number?"}],"returns":[],"function_type":"static","source":{"line":141,"path":"src/Server/Features/Minigames/MinigameUtil.luau"}}],"properties":[],"types":[],"name":"MinigameUtil","desc":"Small server-side helpers shared across the minigame subsystem: map selection,\\nmap load timing, a cross-system variable store, and error reporting.\\n\\n:::note\\nThe module table is named `Minigames` internally but the module \u2014 and this\\ndocumentation class \u2014 is `MinigameUtil`. Require it by path, not by that name.\\n:::\\n\\n### The variable store\\n\\n`set`/`get` read and write attributes on a `Variables` Configuration in\\nReplicatedStorage, created on first require if it does not exist. Because it is\\nan Instance, values replicate to clients for free and outlive any single round \u2014\\nwhich is the point: it is the escape hatch for state that has to cross system\\nboundaries (a day/night toggle, say) without those systems requiring each other.\\nThere is no schema and no validation.\\n\\nGated by [FeatureFlags].Minigames \u2014 disabled by default; per-project forks\\nenable it deliberately. Note the `Variables` Configuration is created at require\\ntime regardless of the flag.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","tags":["dormant"],"realm":["Server"],"source":{"line":30,"path":"src/Server/Features/Minigames/MinigameUtil.luau"}}')}}]);